WITH filtered AS (SELECT id, channel, starts_on, discount_pct, CASE WHEN discount_pct >= 0.28 THEN 'High' WHEN discount_pct >= 0.18 THEN 'Medium' ELSE 'Low' END discount_pct_tier, INITCAP(TRIM(channel)) channel_title, COALESCE(channel, 'N/A') channel_filled FROM promotions WHERE channel IS DISTINCT FROM 'partner' AND channel IS NOT NULL) SELECT id, channel, starts_on, discount_pct, channel_title, channel_filled, AVG(discount_pct) OVER (PARTITION BY channel ORDER BY discount_pct, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_avg_discount_pct, MIN(discount_pct) OVER (PARTITION BY channel ORDER BY discount_pct, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_min_discount_pct, SUM(discount_pct) OVER (PARTITION BY channel ORDER BY discount_pct, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_sum_discount_pct, ROW_NUMBER() OVER (PARTITION BY channel ORDER BY starts_on DESC, id) row_seq FROM filtered WHERE channel IN ('web', 'partner', 'mobile')
